-- Agencias de Grupo FAME por marca (sitio oficial grupofame.com, noviembre 2026)
alter table public.agencies add column if not exists marcas text[], add column if not exists marca_grupo text, add column if not exists tipo text not null default 'agencia', add column if not exists estado text, add column if not exists direccion text;
update public.agencies set name='FAME Morelia · Chevrolet',brand='Chevrolet',marcas=array['Chevrolet']::text[],marca_grupo='Chevrolet',tipo='agencia',city='Morelia',estado='Michoacán',region='Michoacán',direccion='Periférico Paseo De La República, núm. 551, Colonia Los Manantiales, Morelia, Michoacán, C.P. 58186',grupo_id=1 where id=1;
